#include "Engine.h"
#include <stdexcept>
namespace {void check(bool condition,const juce::String& message){if(!condition)throw std::runtime_error(message.toStdString());}}
int runStudioSelfTests(const juce::String& commandLine){
    const auto args=juce::StringArray::fromTokens(commandLine,true);const auto argument=[&](const char* name){const int i=args.indexOf(name);return i>=0&&i+1<args.size()?args[i+1].unquoted():juce::String{};};
    const auto output=argument("--report");const auto directory=juce::File::getSpecialLocation(juce::File::tempDirectory).getNonexistentChildFile("VocalStudio-SelfTest",{},false);directory.createDirectory();juce::StringArray passed;juce::String failure;
    try {StudioEngine engine;engine.prepareForTest();engine.setSessionDirectory(directory);engine.fxBypass.store(true);engine.masterDb.store(0);engine.latencyCompensation.store(false);
        auto started=engine.startRecording(directory);check(started.wasOk(),"start recording: "+started.getErrorMessage());constexpr int block=256,blocks=20;juce::AudioBuffer<float> input(1,block),out(2,block);for(int n=0;n<blocks;++n){for(int i=0;i<block;++i)input.setSample(0,i,.125f*std::sin(static_cast<float>((n*block+i)*.04)));const float* source[]={input.getReadPointer(0)};engine.audioDeviceIOCallbackWithContext(source,1,out.getArrayOfWritePointers(),2,block,{});}
        juce::File take;double position=0;auto finished=engine.finishRecording(take,position);check(finished.wasOk(),"finish recording: "+finished.getErrorMessage());std::unique_ptr<juce::AudioFormatReader> raw(engine.formats.createReaderFor(take));check(raw!=nullptr&&raw->lengthInSamples==block*blocks&&raw->bitsPerSample==24&&raw->numChannels==1,"24-bit dry WAV sample count");juce::AudioBuffer<float> dry(1,block*blocks);check(raw->read(&dry,0,dry.getNumSamples(),0,true,false),"read dry file");for(int i=0;i<dry.getNumSamples();++i)check(std::abs(dry.getSample(0,i)-.125f*std::sin(static_cast<float>(i*.04)))<.000001,"raw recording must remain unprocessed");raw.reset();passed.add("dry recording: exact frames, mono 24-bit and unchanged input");
        std::unique_ptr<StudioTrack> track;check(engine.readTrack(take,true,track).wasOk(),"import recorded track");track->start=0;engine.addTrack(std::move(track));const auto project=directory.getChildFile("Test.vocalstudio");check(engine.saveProject(project).wasOk(),"save project");check(engine.loadProject(project).wasOk(),"reload project");check(engine.getTracks().size()==1,"track state reload");passed.add("atomic project save and state reload");
        {std::atomic<bool> cancelled{false};std::atomic<float> renderProgress{0};vocal::PitchAnalysis analysis;check(engine.analyseTrack(0,analysis,cancelled,renderProgress).wasOk()&&analysis.medianHz>250&&analysis.medianHz<350,"native engine pitch analysis");vocal::PitchOptions options;options.semitones=2;std::unique_ptr<StudioTrack> rendered;check(engine.renderPitchTrack(0,options,rendered,cancelled,renderProgress).wasOk()&&rendered,"native pitch render");check(rendered->audio.getNumSamples()==dry.getNumSamples()&&rendered->originalFile==take&&rendered->file!=take,"pitch render preserves duration and original path");engine.replaceTrack(0,std::move(rendered));check(engine.saveProject(project).wasOk()&&engine.loadProject(project).wasOk(),"save and reload pitch source history");std::unique_ptr<StudioTrack> original;check(engine.restoreOriginalTrack(0,original).wasOk()&&original->file==take,"restore original source after project reload");engine.replaceTrack(0,std::move(original));check(engine.saveProject(project).wasOk(),"save restored project");passed.add("native pitch analysis, render, exact duration and original restoration after project reload");}
        const auto interrupted=directory.getChildFile("Interrupted.recording.wav");juce::MemoryBlock damaged;check(take.loadFileAsData(damaged),"read recovery fixture");auto* bytes=static_cast<unsigned char*>(damaged.getData());for(int i=4;i<8;++i)bytes[i]=0;
        bool foundData=false;for(std::size_t i=12;i+8<damaged.getSize();){const auto size=static_cast<juce::uint32>(bytes[i+4])|(static_cast<juce::uint32>(bytes[i+5])<<8)|(static_cast<juce::uint32>(bytes[i+6])<<16)|(static_cast<juce::uint32>(bytes[i+7])<<24);if(bytes[i]=='d'&&bytes[i+1]=='a'&&bytes[i+2]=='t'&&bytes[i+3]=='a'){for(int j=4;j<8;++j)bytes[i+j]=0;foundData=true;break;}i+=8+size+(size&1);}
        check(foundData&&interrupted.replaceWithData(damaged.getData(),damaged.getSize()),"write stale WAV header fixture");auto recoveryState=engine.projectState();recoveryState.getDynamicObject()->setProperty("recoveringTake",interrupted.getFullPathName());recoveryState.getDynamicObject()->setProperty("recoveringStart",.25);const auto recoveryProject=directory.getChildFile("Recovery.vocalstudio");check(recoveryProject.replaceWithText(juce::JSON::toString(recoveryState)),"write recovery project");
        {StudioEngine recovery;recovery.prepareForTest();check(recovery.loadProject(recoveryProject).wasOk(),"recover interrupted take with stale RIFF lengths");check(recovery.getTracks().size()==2,"recovered take appended");const auto& restored=*recovery.getTracks()[1];check(restored.audio.getNumSamples()==dry.getNumSamples()&&restored.start==.25,"recovered frames and timeline position");for(int i=0;i<dry.getNumSamples();++i)check(std::abs(restored.audio.getSample(0,i)-dry.getSample(0,i))<.000001,"recovered samples unchanged");}
        juce::MemoryBlock untouched;check(interrupted.loadFileAsData(untouched)&&untouched==damaged,"recovery preserves interrupted original");passed.add("crash recovery from stale WAV headers preserves samples and original file");
        const auto finalized=interrupted.getSiblingFile("Interrupted.wav");check(take.copyFileTo(finalized)&&interrupted.deleteFile(),"simulate finalized take before project save");{StudioEngine recovery;recovery.prepareForTest();check(recovery.loadProject(recoveryProject).wasOk()&&recovery.getTracks().size()==2,"recover finalized take after interrupted project update");check(recovery.getTracks()[1]->file==finalized,"reuse finalized take without rewriting");}passed.add("recover finalized take when interrupted before project update");
        std::atomic<bool> cancel{false};std::atomic<float> progress{0};const auto mix=directory.getChildFile("Mix.wav");check(engine.exportMix(mix,cancel,progress).wasOk(),"export mix");std::unique_ptr<juce::AudioFormatReader> reader(engine.formats.createReaderFor(mix));check(reader&&reader->bitsPerSample==24&&reader->numChannels==2,"stereo 24-bit export");juce::AudioBuffer<float> first(2,block*blocks);check(reader->read(&first,0,first.getNumSamples(),0,true,true),"read export");for(int i=100;i<first.getNumSamples()-100;++i)check(std::abs(first.getSample(0,i)-dry.getSample(0,i)*.70710678f)<.00001,"export alignment: compensate limiter latency");reader.reset();passed.add("offline WAV export and sample-aligned limiter compensation");
        engine.fxBypass=false;engine.reverb=0;engine.delay=.3f;engine.delayMs=800;engine.delayFeedback=.65f;engine.threshold=0;engine.ratio=1;engine.makeup=0;const auto tailMix=directory.getChildFile("LongEcho.wav");check(engine.exportMix(tailMix,cancel,progress).wasOk(),"export extended echo tail");{std::unique_ptr<juce::AudioFormatReader> tail(engine.formats.createReaderFor(tailMix));juce::AudioBuffer<float> late(2,4096);check(tail&&tail->lengthInSamples>48000*10&&tail->read(&late,0,4096,static_cast<juce::int64>(48000*4.8),true,true),"extended tail length and read");check(late.getMagnitude(0,4096)>.00001f,"late echo beyond three seconds must remain in mix");}engine.selectPreset(0);engine.fxBypass=true;passed.add("extended delay/reverb export tail preserves audible late echoes");
        const auto preserved=directory.getChildFile("Preserve.wav");preserved.replaceWithText("existing data");cancel.store(true);check(engine.exportMix(preserved,cancel,progress).failed(),"export cancellation");check(preserved.loadFileAsString()=="existing data","cancel must preserve destination");cancel.store(false);passed.add("cancel-safe output without replacing existing file");
        const auto fixture=argument("--fixture");if(fixture.isNotEmpty()){juce::OwnedArray<juce::PluginDescription> descriptions;for(int i=0;i<engine.pluginFormats.getNumFormats();++i)engine.pluginFormats.getFormat(i)->findAllTypesForFile(descriptions,fixture);check(!descriptions.isEmpty(),"discover real VST3 fixture");juce::String error;auto plugin=engine.pluginFormats.createPluginInstance(*descriptions[0],48000,256,error);check(plugin!=nullptr,"instantiate VST3: "+error);check(engine.installPlugin(std::move(plugin)).wasOk(),"install VST3");check(engine.saveProject(project).wasOk()&&engine.loadProject(project).wasOk(),"restore VST3 state");check(engine.pluginInstance()!=nullptr,"VST3 restored");const auto processed=directory.getChildFile("VST3Mix.wav");check(engine.exportMix(processed,cancel,progress).wasOk(),"export VST3 mix");std::unique_ptr<juce::AudioFormatReader> vst(engine.formats.createReaderFor(processed));juce::AudioBuffer<float> data(2,block*blocks);check(vst&&vst->read(&data,0,data.getNumSamples(),0,true,true),"read plugin mix");for(int i=200;i<data.getNumSamples()-100;++i)check(std::abs(data.getSample(0,i)-dry.getSample(0,i)*.35355339f)<.00001,"VST3 latency compensation and processing");passed.add("real VST3 loading, project state, processing and latency compensation");}
    } catch(const std::exception& e){failure=e.what();}
    auto* report=new juce::DynamicObject();report->setProperty("passed",failure.isEmpty());report->setProperty("checks",passed);report->setProperty("error",failure);report->setProperty("files",directory.getFullPathName());if(output.isNotEmpty()){const juce::File file(output);file.getParentDirectory().createDirectory();file.replaceWithText(juce::JSON::toString(juce::var(report),true));}else {juce::Logger::writeToLog(juce::JSON::toString(juce::var(report),true));}
    return failure.isEmpty()?0:1;
}
